#!/usr/bin/env python3
"""Build a browser lesson surface from the current shared lesson-card model."""

from __future__ import annotations

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "research/shared-lesson-cards.json"
OUT = ROOT / "writeups/shared-lesson-cards.html"


def main() -> int:
    cards = json.loads(DATA.read_text())["cards"]
    payload = json.dumps(cards, ensure_ascii=False).replace("</", "<\\/")
    document = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Best Speech Analysis — Lesson Cards</title><style>:root{{font-family:system-ui,sans-serif;color:#1d2935;background:#f5f3ee}}body{{margin:0}}header{{background:#17212b;color:white;padding:28px max(20px,calc((100vw - 1160px)/2))}}main{{max-width:1160px;margin:22px auto;padding:0 20px 60px}}.notice{{background:#fff7d6;border:1px solid #d8bd61;border-radius:8px;padding:14px}}.controls{{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}}input,select{{font:inherit;padding:9px;border:1px solid #aab3bb;border-radius:6px}}.card{{background:white;border:1px solid #d6d0c7;border-radius:10px;margin:16px 0;padding:18px}}.meta,.muted{{color:#5c6872;font-size:.9rem}}.tag{{display:inline-block;background:#e2edf5;border-radius:99px;padding:3px 8px;margin:2px;font-size:.82rem}}details{{margin-top:12px;border-top:1px solid #e1e5e8;padding-top:10px}}summary{{cursor:pointer;font-weight:650}}.example{{background:#f4f8fb;border-left:4px solid #39739d;padding:10px;margin:10px 0}}.task{{background:#f8f6ef;border-left:4px solid #a87921;padding:10px;margin:8px 0}}a{{color:#075985}}pre{{white-space:pre-wrap}}</style></head><body><header><h1>Lesson cards</h1><p>Evidence-linked provisional lessons for practising communication choices.</p></header><main><div class="notice"><b>Evidence boundary:</b> These 18 cards are provisional practice hypotheses. Transcript evidence, delivery queues, recurrence, learner status and listener status remain separate. They do not prove effectiveness, intent or universal best practice. The current learner protocol is <a href="communication-job-learner-check.html">available separately</a>.</div><div class="controls"><label>Search <input id="search" placeholder="problem, job or phrase"></label><label>Job <select id="job"><option value="">All jobs</option>{''.join(f'<option value="{i}">{i}</option>' for i in sorted({c['canonical_job'] for c in cards}))}</select></label><label>Status <select id="status"><option value="">All statuses</option><option value="provisional_not_validated">Provisional</option></select></label></div><p id="count"></p><section id="cards"></section></main><script id="card-data" type="application/json">{payload}</script><script>const cards=JSON.parse(document.querySelector('#card-data').textContent),out=document.querySelector('#cards'),search=document.querySelector('#search'),job=document.querySelector('#job'),status=document.querySelector('#status'),count=document.querySelector('#count');const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));const link=v=>v?'<a href="https://www.youtube.com/watch?v='+esc(v.split(':')[0])+'" target="_blank" rel="noopener">source</a>':'source unavailable';function example(x){{const text=(x.exact_segments||[]).map(s=>s.text||'').join(' ');return '<div class="example"><b>'+esc(x.evidence_id||x.record_id)+'</b> · '+esc(x.title||'')+' · '+link(x.evidence_id||x.record_id)+'<p>'+esc(text||x.transcript_excerpt||'')+'</p><p class="muted">Function/context remains provisional; transcript wording is not silently repaired.</p></div>'}}function delivery(x){{return '<div class="example"><b>'+esc(x.sample_id)+'</b> · '+esc(x.raw_media_state)+'<p>'+esc(x.transcript_excerpt)+'</p><p class="muted">Manual observations: '+esc(JSON.stringify(x.review||{{}}))+'</p><p class="muted">Proxy limits: '+esc(JSON.stringify((x.measurement||{{}}).measurement_limits||[]))+'</p></div>'}}function card(x){{return '<article class="card"><div class="meta">'+esc(x.canonical_job)+' · '+esc(x.card_id)+' · '+esc(x.status)+'</div><h2>'+esc(x.communication_problem)+'</h2><p><b>Repeatable form:</b> '+esc(x.repeatable_form)+'</p><p><b>Why it might help:</b> '+esc(x.mechanism_hypothesis)+'</p><p><span class="tag">'+x.examples.length+' exact examples</span><span class="tag">'+x.counterexamples.length+' limitation slots</span><span class="tag">'+x.delivery_evidence.observations.length+' delivery samples</span><span class="tag">learner: '+esc(x.validation.learner_status)+'</span></p><details open><summary>Exact language and context</summary>'+x.examples.map(example).join('')+'</details><details><summary>Delivery evidence and missingness</summary>'+x.delivery_evidence.observations.map(delivery).join('')+'<p class="muted">'+esc(x.delivery_evidence.boundary)+'</p></details><details><summary>Practice and self-check</summary><p>'+esc(x.practice.hypothesis)+'</p><p><b>Self-check:</b> '+esc(x.practice.self_check)+'</p><p><b>When not to use:</b> '+esc(x.practice.non_fit)+'</p></details><details><summary>Validation, limits and listener separation</summary><pre>'+esc(JSON.stringify({{validation:x.validation,recurrence:x.recurrence,limits:x.limits,evidence_chain:x.evidence_chain}},null,2))+'</pre></details></article>'}}function render(){{const q=search.value.toLowerCase(),j=job.value,s=status.value,rows=cards.filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!j||x.canonical_job===j)&&(!s||x.status===s));count.textContent=rows.length+' of '+cards.length+' lesson cards';out.innerHTML=rows.map(card).join('')||'<p>No matching lesson card.</p>'}}search.oninput=render;job.onchange=render;status.onchange=render;render();</script></body></html>'''
    OUT.write_text(document)
    print(f"wrote {OUT.relative_to(ROOT)} ({len(cards)} cards)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
